          "sourceLine": 16,
          "sourceRecord": 49,
          "gurmukhi": "ਨਾਨਕ ਜਿਹ ਘਟਿ ਵਸੈ ਹਰਿ ਨਾਮੁ ॥੮॥੩॥",
          "id": "sukhmani.a03.p08.l10",
