          "sourceLine": 8,
          "sourceRecord": 23,
          "gurmukhi": "ਪ੍ਰਭ ਭਾਵੈ ਸੋਈ ਫੁਨਿ ਹੋਗੁ ॥",
          "id": "sukhmani.a09.p08.l04",
